/**
 * The subtitle of the main banner and of the social preview as outlines, one entry per word, so the build needs no font at run time.
 *
 * Same font and method as github-wordmark.mjs, at a lighter weight: Adwaita Sans SemiBold (wght 600, opsz 14; SIL Open Font License 1.1,
 * GNOME adwaita-fonts), each word shaped with HarfBuzz on its own, drawn y-down with the baseline at y = 0 and the pen at x = 0, in font
 * units (2048 per em). A line is its words at their advances with the space advance between them. The punctuation belongs to the word it
 * follows ("runtime,"), so the words of a line can be moved to another line without being shaped again.
 *
 * Made with this script (fontTools and HarfBuzz's hb-shape). Save it as a file and run
 *   python3 SCRIPT ~/.local/share/fonts/adwaita-sans-fonts/AdwaitaSans-Regular.ttf 600 "<SUBTITLE_TEXT>"
 * and take "advance", "bounds" and "d" of each word from its output:
 *
 *   import json, subprocess, sys
 *   from fontTools.ttLib import TTFont
 *   from fontTools.varLib.instancer import instantiateVariableFont
 *   from fontTools.pens.svgPathPen import SVGPathPen
 *   from fontTools.pens.transformPen import TransformPen
 *   from fontTools.pens.boundsPen import BoundsPen
 *
 *   FONT, WEIGHT, TEXT = sys.argv[1], int(sys.argv[2]), sys.argv[3]
 *   font = instantiateVariableFont(TTFont(FONT), {'wght': WEIGHT, 'opsz': 14})
 *   glyphs = font.getGlyphSet()
 *   out = {'upem': font['head'].unitsPerEm, 'words': {}}
 *   for word in [' '] + TEXT.split(' '):
 *       shaped = json.loads(subprocess.check_output(['hb-shape', f'--font-file={FONT}', f'--variations=wght={WEIGHT},opsz=14', '--output-format=json', word]))
 *       pen = SVGPathPen(glyphs, ntos=lambda v: str(int(v)) if v == int(v) else ('%.1f' % v))
 *       bounds = BoundsPen(glyphs)
 *       x = 0
 *       for g in shaped:
 *           for p in (pen, bounds):
 *               glyphs[g['g']].draw(TransformPen(p, (1, 0, 0, -1, x + g['dx'], -g['dy'])))
 *           x += g['ax']
 *       out['words'][word] = {'advance': x, 'bounds': bounds.bounds, 'd': pen.getCommands()}
 *   print(json.dumps(out))
 *
 * `test/github-subtitle.test.mjs` pins the text and a hash of the outlines.
 */

/** The maintainer's own words. A layout draws these and no others; where the lines break is the layout's to say. */
export const SUBTITLE_TEXT = 'A SillyTavern fork with a Bun runtime, detailed human interface guidelines, and modernised features!';
export const SUBTITLE_WEIGHT = 600;
export const SUBTITLE_UNITS_PER_EM = 2048;
/** The distance from one baseline to the next, as a share of the font size. */
const SUBTITLE_LINE_HEIGHT = 1.3;
/** The height of the lowercase x in font units, which is what a reader's eye takes the size of a text from. */
const SUBTITLE_X_HEIGHT = 1118;

