const SPACE = SUBTITLE_WORDS[' '].advance;
const ALIGNMENTS = Object.freeze(['left', 'centre']);

/** The height of the lowercase letters in pixels at a font size. @param {number} size */
export const subtitleXHeight = (size) => (size * SUBTITLE_X_HEIGHT) / SUBTITLE_UNITS_PER_EM;

/**
 * Parses the lines of a subtitle: whole words of SUBTITLE_TEXT, in order, none left out and none added, so the wording stays the
 * maintainer's while the breaks are free.
 * @param {unknown} lines
 * @param {string} where for the error
 * @returns {string[]}
 */
export function parseSubtitleLines(lines, where) {
    if (!Array.isArray(lines) || lines.length === 0 || lines.some((line) => typeof line !== 'string' || line === '')) {
        throw new Error(`${where}.lines must be a list of lines of text.`);
    }
    if (lines.join(' ') !== SUBTITLE_TEXT) {
        throw new Error(`${where}.lines read "${lines.join(' ')}", which is not the subtitle "${SUBTITLE_TEXT}". The lines may break it anywhere between words and may not change it.`);
    }
    return lines;
}

/** @param {unknown} align @param {string} where */
export function parseSubtitleAlign(align, where) {
    if (!ALIGNMENTS.includes(align)) {
        throw new Error(`${where}.align must be one of ${ALIGNMENTS.join(', ')}, got ${JSON.stringify(align)}.`);
    }
    return align;
}

/** Each line of the subtitle with its words, its first baseline at 0, and its ink extent from the pen at 0, in font units. */
function setLines(lines) {
    return lines.map((line, index) => {
        const words = line.split(' ').map((word) => {
            if (!Object.hasOwn(SUBTITLE_WORDS, word) || word === ' ') {
                throw new Error(`"${word}" is not one of the words of the subtitle, so there is no outline of it to draw.`);
            }
            return SUBTITLE_WORDS[word];
        });
        const baseline = index * SUBTITLE_LINE_HEIGHT * SUBTITLE_UNITS_PER_EM;
        let pen = 0;
        const placed = [];
        let right = 0;
        words.forEach((word) => {
            placed.push({ x: pen, d: word.d });
            right = pen + word.ink.right;
            pen += word.advance + SPACE;
        });
        return {
            placed,
            baseline,
            left: words[0].ink.left,
            right,
            top: baseline + Math.min(...words.map(({ ink }) => ink.top)),
            bottom: baseline + Math.max(...words.map(({ ink }) => ink.bottom)),
        };
    });
}

/** The box of the whole subtitle in font units, and where each line starts so that the lines are aligned in it. */
function setSubtitle(lines, align) {
    const set = setLines(lines);
    const width = Math.max(...set.map(({ left, right }) => right - left));
    const top = Math.min(...set.map((line) => line.top));
    const bottom = Math.max(...set.map((line) => line.bottom));
    const starts = set.map(({ left, right }) => (align === 'left' ? 0 : (width - (right - left)) / 2) - left);
    return { set, starts, box: { width, top, bottom } };
}

/**
 * The pixel size of the subtitle's ink at a font size, so a layout can place it before it is drawn.
 * @param {string[]} lines
 * @param {{ size: number }} options
 */
export function subtitleSize(lines, { size }) {
    const { box } = setSubtitle(lines, 'left');
    const scale = size / SUBTITLE_UNITS_PER_EM;
    return { width: Math.round(box.width * scale), height: Math.round((box.bottom - box.top) * scale) };
}

/**
 * The subtitle as outlines in one flat colour.
 * @param {{ lines: string[], size: number, colour: string, align: 'left' | 'centre' }} options
 * @returns {Promise<Raster>}
 */
export function drawSubtitle({ lines, size, colour, align }) {
    const { set, starts, box } = setSubtitle(lines, align);
    const { width, height } = subtitleSize(lines, { size });
    const paths = set.flatMap(({ placed, baseline }, at) => placed.map(({ x, d }) => `<path transform="translate(${x + starts[at]} ${baseline})" d="${d}"/>`)).join('');
    return rasteriseSvg(`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 ${box.top} ${box.width} ${box.bottom - box.top}"><g fill="${colour}">${paths}</g></svg>`);
}
